import { createHash } from "node:crypto"
import { format } from "prettier"
import { siteOrigin } from "../site"
import type { BuildOutput } from "./build-site"

/**
 * The generated files committed in src/ (products import them, so they
 * must exist before any build): typed links, the topics index for product
 * Ctrl K, Stuart's knowledge bundle and the MCP tool schemas. A test and
 * `pnpm --filter @matchbox/docs check` fail when they are out of date.
 */

const header =
  "// Generated by packages/docs/scripts/build.ts from packages/docs/content.\n// Do not edit: run `pnpm --filter @matchbox/docs generate`.\n"

export function linksModule(topics: ReadonlyMap<string, string>): string {
  const entries = [...topics.entries()].sort(([a], [b]) => a.localeCompare(b))
  const lines = entries.map(
    ([key, path]) => `  ${JSON.stringify(key)}: ${JSON.stringify(path)},`,
  )
  return `${header}
/** The docs origin every product links to. */
export const docsOrigin = ${JSON.stringify(siteOrigin)}

/** Every page and anchor a product may link to, by stable key. */
export const docsTopics = {
${lines.join("\n")}
} as const

export type DocsTopic = keyof typeof docsTopics

/**
 * The absolute URL of a docs topic. Renaming or deleting a page removes
 * its key, so every product that links to it stops compiling.
 */
export function docsUrl(topic: DocsTopic): string {
  return \`\${docsOrigin}\${docsTopics[topic]}\`
}
`
}

export function knowledgeModule(
  knowledge: BuildOutput["knowledge"],
  titles: ReadonlyMap<string, string>,
): string {
  const entries = knowledge.flatMap(({ page, entries: own }) =>
    own.map((entry) => ({
      ...entry,
      // Stuart cites the docs page first, then the source it was checked against.
      sources: [
        {
          label: `Matchbox Docs, ${titles.get(page) ?? page}`.slice(0, 60),
          url: `${siteOrigin}${page}`,
        },
        ...entry.sources,
      ],
    })),
  )
  const body = JSON.stringify(entries, null, 2)
  const version = createHash("sha256").update(body).digest("hex").slice(0, 12)
  return `${header}
/**
 * Stuart's reviewed notes, written beside the concept pages they explain.
 * Same shape as \`KnowledgeEntry\` in apps/stuart/src/query/knowledge/mezo.ts.
 */
export type DocsKnowledgeEntry = {
  id: string
  title: string
  answer: string
  detail: string[]
  facts: Array<{ label: string; display: string }>
  keywords: string[]
  sources: Array<{ label: string; url: string }>
}

/** Changes whenever any entry changes. */
export const docsKnowledgeVersion = ${JSON.stringify(version)}

export const docsKnowledge: readonly DocsKnowledgeEntry[] = ${body}
`
}

/** JSON as Prettier writes it, so `pnpm lint` and the check agree. */
export function formatJson(value: unknown): Promise<string> {
  return format(JSON.stringify(value), { parser: "json" })
}

export async function generatedFiles(
  output: BuildOutput,
): Promise<Map<string, string>> {
  const titles = new Map(
    Object.values(output.manifest.pages).map((page) => [page.path, page.title]),
  )
  const files = new Map<string, string>()
  files.set("src/links.gen.ts", linksModule(output.topics))
  files.set("src/topics.gen.json", await formatJson(output.topicsIndex))
  files.set("src/knowledge.gen.ts", knowledgeModule(output.knowledge, titles))
  return files
}
